import {gameDecisions} from './game-performance.js';
import {resultAccuracy,ACCURACY_METHOD} from './accuracy-metric.js';
import {tacticalTheme,storedTheme} from './tactics.js';
import {Chess} from './vendor/chess.js';
let database;
export function db(){if(!database)database=new Promise((resolve,reject)=>{const r=indexedDB.open('plystreak-records',1);r.onupgradeneeded=()=>{for(const s of ['games','attempts','meta'])r.result.createObjectStore(s,{keyPath:'id'})};r.onsuccess=()=>{r.result.onversionchange=()=>{r.result.close();database=null;};resolve(r.result)};r.onerror=()=>{database=null;reject(Error('Archivio locale non disponibile. Esporta i PGN per conservarli.'))}});return database}
export async function readAll(store='games'){const d=await db();return new Promise((resolve,reject)=>{const r=d.transaction(store).objectStore(store).getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
export async function getRecord(id,store='games'){const d=await db();return new Promise((resolve,reject)=>{const r=d.transaction(store).objectStore(store).get(id);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
export async function putRecord(record,store='games'){const d=await db();return new Promise((resolve,reject)=>{const t=d.transaction(store,'readwrite');t.objectStore(store).put(record);t.oncomplete=()=>resolve(record);t.onerror=t.onabort=()=>reject(t.error||Error('Salvataggio interrotto. Riprova prima di chiudere.'))})}
export async function gameId(pgn){const c=new Chess();c.loadPgn(pgn);const h=c.getHeaders();const identity=[h.Site,h.Date,h.UTCDate,h.UTCTime,h.White,h.Black,c.history({verbose:true})[0]?.before,c.history().join(' ')].join('|');return 'pgn-'+stableId(identity)}
export function inferSide(headers){let name='';try{name=localStorage.getItem('plystreak-chess-user')||''}catch{}return headers.White?.toLowerCase()===name.toLowerCase()&&name?'w':headers.Black?.toLowerCase()===name.toLowerCase()&&name?'b':null}
async function writeGame({id,pgn,source='import',side,analysis,playedAt,extra={}}){const c=new Chess();c.loadPgn(pgn);const headers=c.getHeaders();id=id||await gameId(pgn);const old=await getRecord(id);const record={...old,id,pgn,source:old?.source||source,headers,side:side===undefined?(old?.side||inferSide(headers)):side,playedAt:playedAt||old?.playedAt||pgnDate(headers)||Date.now(),recordedAt:old?.recordedAt||Date.now(),updatedAt:Date.now(),plies:c.history().length,...extra};if(analysis!==undefined)record.analysis=analysis;return putRecord(record)}
export const THEMES={material:'Pezzi e catture',king:'Sicurezza del re',position:'Scelte di posizione',fork:'Doppi attacchi',pin:'Inchiodature',hanging:'Pezzi indifesi'};
export const mistakeTheme=tacticalTheme;
export function analysisRecord(moves,grades,results){const details=moves.map((m,i)=>grades[i]?{ply:i,side:m.color,san:m.san,from:m.from,to:m.to,promotion:m.promotion,fen:m.before,afterFen:m.after,loss:grades[i].loss,accuracy:grades[i].accuracy,type:grades[i].type,theme:mistakeTheme(m,grades[i].reviewAfter||results[i+1]),best:(grades[i].reviewBefore||results[i])?.lines?.[0]?.pv?.[0],verification:grades[i].verification}:null).filter(Boolean);return {performanceBasis:{version:1,w:gameDecisions(moves,results,'w'),b:gameDecisions(moves,results,'b')},accuracyMethod:ACCURACY_METHOD,gameAccuracy:resultAccuracy(moves,results),version:2,complete:details.length===moves.length,total:moves.length,details,at:Date.now(),method:'Stockfish 19 Lite · profondità massima 20 / 2200 ms'}}
export function personalStats(games){const identified=games.filter(g=>['w','b'].includes(g.side));const finished=identified.filter(g=>['1-0','0-1','1/2-1/2'].includes(g.headers?.Result));const outcome=g=>g.headers.Result==='1/2-1/2'?'draw':(g.headers.Result==='1-0')===(g.side==='w')?'win':'loss';const analyzed=identified.filter(g=>g.analysis?.version===2&&g.analysis.complete).sort((a,b)=>a.playedAt-b.playedAt);const metricMethod=analyzed.at(-1)?.analysis.accuracyMethod;const metricGames=analyzed.filter(g=>g.analysis.accuracyMethod===metricMethod);const averages=metricGames.map(g=>{const ds=g.analysis.details.filter(d=>d.side===g.side);return {id:g.id,date:g.playedAt,value:g.analysis.gameAccuracy?.[g.side]??(ds.length?ds.reduce((s,d)=>s+d.accuracy,0)/ds.length:null)}}).filter(x=>x.value!==null);const themes={material:0,king:0,position:0};for(const g of analyzed)for(const m of g.analysis.details)if(m.side===g.side&&m.loss>.05){const theme=storedTheme(m);themes[theme]=(themes[theme]||0)+1};const mean=a=>a.length?a.reduce((s,x)=>s+x.value,0)/a.length:null;const recent=averages.slice(-5),previous=averages.slice(-10,-5);return {total:games.length,identified:identified.length,finished:finished.length,wins:finished.filter(g=>outcome(g)==='win').length,draws:finished.filter(g=>outcome(g)==='draw').length,losses:finished.filter(g=>outcome(g)==='loss').length,analyzed:analyzed.length,averages,accuracy:mean(averages),delta:recent.length===5&&previous.length===5?mean(recent)-mean(previous):null,themes}}
export function errorPositions(games){const errors=[];for(const g of games)if(g.side&&g.analysis?.version===2&&g.analysis.complete)for(const m of g.analysis.details)if(m.side===g.side&&m.loss>.05&&m.best)errors.push({...m,theme:storedTheme(m),id:g.id+':'+m.ply,gameId:g.id,date:g.playedAt});const freq={};for(const e of errors)freq[e.theme]=(freq[e.theme]||0)+1;return errors.sort((a,b)=>(freq[b.theme]-freq[a.theme])||(b.loss-a.loss))}
export function mirrorFen(fen){const [board,turn,rights,ep,half,full]=fen.split(' ');const swap=s=>s.replace(/[a-zA-Z]/g,c=>c===c.toUpperCase()?c.toLowerCase():c.toUpperCase());const r=swap(rights);return [board.split('/').reverse().map(swap).join('/'),turn==='w'?'b':'w','KQkq'.split('').filter(c=>r.includes(c)).join('')||'-',ep==='-'?'-':ep[0]+(9-Number(ep[1])),half,full].join(' ')}

const saves=new Map();export function saveGame(record){const key=record.id||record.pgn;const previous=saves.get(key)||Promise.resolve();const pending=previous.catch(()=>{}).then(()=>writeGame(record));saves.set(key,pending);pending.finally(()=>{if(saves.get(key)===pending)saves.delete(key)}).catch(()=>{});return pending}

export function pgnDate(h){const d=h.UTCDate||h.Date;if(!/^\d{4}\.\d{2}\.\d{2}$/.test(d||''))return null;const t=Date.parse(d.replaceAll('.','-')+'T'+(/^\d{2}:\d{2}:\d{2}$/.test(h.UTCTime||'')?h.UTCTime:'12:00:00')+'Z');return Number.isFinite(t)?t:null}

export function newId(){return [...crypto.getRandomValues(new Uint32Array(4))].map(n=>n.toString(16).padStart(8,'0')).join('')}
function stableId(s){return [2166136261,3339675911,2246822507,3266489909].map(seed=>{let h=seed;for(let i=0;i<s.length;i++)h=Math.imul(h^s.charCodeAt(i),16777619);return (h>>>0).toString(16).padStart(8,'0')}).join('')}
